def transform_with_none(seq, limit):
    new_seq = []
    for i in range(len(seq) - 1):
        new_seq.append(seq[i])
        x = seq[i]
        y = seq[i+1]
        if x is not None and y is not None:
            s = x + y
            if s <= limit:
                new_seq.append(s)
            else:
                new_seq.append(None)
        else:
            new_seq.append(None)
    new_seq.append(seq[-1])
    return new_seq

def solve_with_limit(n_initial, target, t_max):
    seq = list(range(1, n_initial + 1))
    for t in range(1, t_max + 1):
        seq = transform_with_none(seq, target)
        # To prevent the sequence from growing too large, 
        # we only keep elements that are not None.
        # Wait, that's not right. We need to keep None to maintain adjacency.
        # But if we have a long string of Nones, they don't do anything.
        # Let's compress consecutive Nones into a single None.
        new_seq = []
        for x in seq:
            if x is None:
                if not new_seq or new_seq[-1] is not None:
                    new_seq.append(None)
            else:
                new_seq.append(x)
        seq = new_seq
    return seq.count(target)

